namespace DiwaliGameplay {
public static class GameplayVerification {
 static readonly List<object> results=new List<object>();
 static NearFarInteractor hand; static GrabbableItem held; static Vector3 handToItem;
 static string reportPath="../Game_Plans/Gameplay_RealInput_Full_2026-10-21.json";static string report=>Path.GetFullPath(reportPath);
 static FireworksGame stagedFireworks;
 static void Check(string name,bool pass,string detail=""){results.Add(new{name,pass,detail});Save("running");if(!pass)Debug.LogWarning("Gameplay QA: "+name+" "+detail);}
 static void Save(string state){File.WriteAllText(report,Newtonsoft.Json.JsonConvert.SerializeObject(new{state,time=DateTime.Now.ToString("s"),scope="Unity Play Mode synthetic NearFar controller casts, queued grip input, and XRUIInputModule button presses. Not physical headset verification.",results},Newtonsoft.Json.Formatting.Indented));}
 static async Task Frames(int n=3){for(int i=0;i<n;i++)await Task.Delay(35);}
 static Bounds GrabBounds(GrabbableItem item){var active=item.grab?item.grab.colliders.Where(c=>c&&c.enabled&&c.gameObject.activeInHierarchy).ToArray():Array.Empty<Collider>();if(active.Length==0)return GameObjectUtility.BoundsOf(item.transform);var b=active[0].bounds;for(int i=1;i<active.Length;i++)b.Encapsulate(active[i].bounds);return b;}
 static async Task Hold(GrabbableItem item,Vector3 position){await ReleaseAndWait();var bounds=GrabBounds(item);var colliders=item.grab.colliders.Where(c=>c&&c.enabled&&c.gameObject.activeInHierarchy).ToArray();var dirs=new[]{Vector3.forward,Vector3.back,Vector3.right,Vector3.left,Vector3.up,Vector3.up+Vector3.forward,Vector3.up+Vector3.back,Vector3.up+Vector3.right,Vector3.up+Vector3.left};bool target=false;foreach(var col in colliders){foreach(var dir0 in dirs){var dir=dir0.normalized;hand.transform.SetPositionAndRotation(col.bounds.center+dir*.75f,Quaternion.LookRotation(-dir,Vector3.up));await Frames(3);var candidates=new List<IXRInteractable>();hand.GetValidTargets(candidates);if(candidates.Contains(item.grab)){target=true;break;}}if(target)break;}Check("NearFar cast targets "+item.itemId,target);if(!target)return;hand.selectInput.QueueManualState(true,1f);await Frames(4);held=item;Check("Queued NearFar grip selects "+item.itemId,item.IsHeld);if(!item.IsHeld){held=null;hand.selectInput.QueueManualState(false,0f);return;}handToItem=item.transform.position-hand.transform.position;await Move(position);}
 static async Task DragSlider(VenueGame game,string label,float target){await ReleaseAndWait();var slider=game.GetComponentsInChildren<Slider>(true).FirstOrDefault(s=>s.gameObject.activeInHierarchy&&s.interactable);Check(game.GetType().Name+" slider present for tracked drag "+label,slider!=null);if(!slider)return;var rect=slider.GetComponent<RectTransform>();var canvas=slider.GetComponentInParent<Canvas>();if(!rect||!canvas)return;var forward=canvas.transform.forward;var start=rect.TransformPoint(new Vector3(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,.12f),rect.rect.center.y,0));var end=rect.TransformPoint(new Vector3(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,target),rect.rect.center.y,0));hand.transform.SetPositionAndRotation(start-forward*1.25f,Quaternion.LookRotation(forward,Vector3.up));await Frames(5);hand.uiPressInput.QueueManualState(true,1f);await Frames(4);hand.transform.SetPositionAndRotation(end-forward*1.25f,Quaternion.LookRotation(forward,Vector3.up));await Frames(12);hand.uiPressInput.QueueManualState(false,0f);await Frames(6);Check(game.GetType().Name+" tracked UI press-drag changes slider "+label,Mathf.Abs(slider.value-target)<.15f,$"value={slider.value:F3},target={target:F3}");}
 static void Release(){if(hand)hand.selectInput.QueueManualState(false,0f);held=null;}
 static async Task ReleaseAndWait(){Release();await Frames(4);}
 static async Task Move(Vector3 p){var item=held;var collider=item&&item.grab?item.grab.colliders.FirstOrDefault(x=>x&&x.enabled):null;Vector3 before=collider?collider.bounds.center:Vector3.zero;Vector3 start=item?item.transform.position:Vector3.zero;hand.transform.position=p-handToItem;await Frames(8);if(item&&collider&&(p-start).magnitude>.2f)Check("Visible collider/mesh follows tracked hand: "+item.itemId,(collider.bounds.center-before).magnitude>.05f);}
 static Button ButtonFor(VenueGame game,string name)=>game.GetComponentsInChildren<Button>(true).FirstOrDefault(b=>b.name==name);
 static string RenderPanel(string label,VenueGame game){var panel=game.GetComponentInChildren<VenuePanel>();return ChristmasIslandQA.Render(label,panel.transform.position-panel.transform.forward*2.4f,panel.transform.position,58);}
 static bool CullOff(Renderer renderer,out string detail){var mats=renderer?renderer.sharedMaterials.Where(m=>m&&m.HasProperty("_Cull")).Distinct().ToArray():Array.Empty<Material>();detail=string.Join(",",mats.Select(m=>m.name+"="+m.GetFloat("_Cull").ToString("F0")));return mats.Length>0&&mats.All(m=>Mathf.Abs(m.GetFloat("_Cull"))<.001f);}
 static void KeyShaft(DiyaGame game,out Vector3 axis,out Vector3 tip){var art=game.key.GetComponentsInChildren<MeshFilter>(true).First(x=>x.sharedMesh);var mesh=art.sharedMesh;Vector3[] vertices;using(var data=MeshUtility.AcquireReadOnlyMeshData(mesh)){using(var native=new NativeArray<Vector3>(data[0].vertexCount,Allocator.Temp)){data[0].GetVertices(native);vertices=new Vector3[native.Length];native.CopyTo(vertices);}}var b=mesh.bounds;int longest=0;if(b.size.y>b.size.x)longest=1;if(b.size.z>b.size[longest])longest=2;var local=Vector3.zero;local[longest]=1;float min=vertices.Min(v=>v[longest]),max=vertices.Max(v=>v[longest]);float width=(max-min)*.22f;float Spread(bool high){var vs=vertices.Where(p=>high?p[longest]>max-width:p[longest]<min+width).ToArray();if(vs.Length==0)return 0;var c=vs.Aggregate(Vector3.zero,(a,v)=>a+v)/vs.Length;return vs.Max(v=>Vector3.ProjectOnPlane(v-c,local).sqrMagnitude);}if(Spread(true)>Spread(false))local=-local;axis=art.transform.TransformDirection(local).normalized;var far=vertices.OrderByDescending(v=>Vector3.Dot(v,local)).First();tip=art.transform.TransformPoint(far);}
 static async Task Click(VenueGame g,string name){await ReleaseAndWait();await Frames();var b=ButtonFor(g,name);Check(g.GetType().Name+" visible enabled UI "+name,b&&b.gameObject.activeInHierarchy&&b.interactable);if(!b||!b.gameObject.activeInHierarchy||!b.interactable)return;var panel=b.GetComponentInParent<Canvas>();var center=b.GetComponent<RectTransform>().TransformPoint(b.GetComponent<RectTransform>().rect.center);hand.transform.SetPositionAndRotation(center-panel.transform.forward*1.25f,Quaternion.LookRotation(panel.transform.forward,Vector3.up));await Frames(4);var ray=new TrackedDeviceEventData(EventSystem.current){rayPoints=new List<Vector3>{hand.transform.position,center+panel.transform.forward*.1f},layerMask=~0};var hits=new List<RaycastResult>();panel.GetComponent<TrackedDeviceGraphicRaycaster>().Raycast(ray,hits);bool rayHit=hits.Any(x=>x.gameObject==b.gameObject);Check(g.GetType().Name+" tracked ray reaches "+name,rayHit,"hits="+string.Join(",",hits.Select(x=>x.gameObject.name)));int clicks=0;UnityEngine.Events.UnityAction onClick=()=>clicks++;b.onClick.AddListener(onClick);hand.uiPressInput.QueueManualState(true,1f);await Frames(5);hand.uiPressInput.QueueManualState(false,0f);await Frames(5);b.onClick.RemoveListener(onClick);Check(g.GetType().Name+" XRUIInputModule press dispatches "+name,clicks==1,"clicks="+clicks);}
 static void PreparePlayerPanel(string typeName,bool help){if(!EditorApplication.isPlaying)return;var game=UnityEngine.Object.FindObjectsByType<VenueGame>(FindObjectsSortMode.None).FirstOrDefault(g=>g.GetType().Name==typeName);if(!game)return;var panel=game.GetComponentInChildren<VenuePanel>();var cam=Camera.main;if(!panel||!cam)return;Vector3 approach=typeName=="SweetGame"?new Vector3(-29.5f,1.5f,4.2f):typeName=="RangoliGame"?new Vector3(-20.5f,1.5f,33.5f):typeName=="RoutingGame"?new Vector3(28f,1.5f,35.6f):typeName=="DiyaGame"?new Vector3(31f,1.5f,7.7f):new Vector3(0f,1.5f,58.5f);var root=cam.transform.root;var dir=Vector3.ProjectOnPlane(panel.transform.position-cam.transform.position,Vector3.up);var cameraLocalToRoot=Quaternion.Inverse(root.rotation)*cam.transform.rotation;if(dir.sqrMagnitude>.01f)root.rotation=Quaternion.LookRotation(dir.normalized,Vector3.up)*Quaternion.Inverse(cameraLocalToRoot);root.position+=approach-cam.transform.position;panel.FaceToward(cam.transform.position);if(help)panel.ShowHelp();else panel.CloseHelp();Canvas.ForceUpdateCanvases();Debug.Log($"Player panel view prepared: {typeName}, help={help}, camera={cam.transform.position}, panel={panel.transform.position}, playerForward={cam.transform.forward}");}
