 [MenuItem("Diwali/Gameplay/Measure Sweet Counter Surface")]
 public static async void MeasureSweetCounterSurface(){if(!EditorApplication.isPlaying)return;var g=UnityEngine.Object.FindFirstObjectByType<SweetGame>();var venue=GameObjectUtility.FindExact("SweetShop - Approved Warm Palette");var top=venue?venue.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Cube.012"):null;var mesh=top?top.GetComponent<MeshFilter>()?.sharedMesh:null;if(!g||!top||!mesh)return;var bins=new Dictionary<int,float>();var v=mesh.vertices;var tri=mesh.triangles;for(int i=0;i+2<tri.Length;i+=3){var a=top.TransformPoint(v[tri[i]]);var b=top.TransformPoint(v[tri[i+1]]);var c=top.TransformPoint(v[tri[i+2]]);if(Mathf.Abs(a.y-b.y)<.001f&&Mathf.Abs(a.y-c.y)<.001f){int key=Mathf.RoundToInt(((a.y+b.y+c.y)/3)*100);float area=Mathf.Abs(Vector3.Cross(b-a,c-a).y)*.5f;if(area>.000001f)bins[key]=bins.GetValueOrDefault(key)+area;}}var basket=g.basket;var p=basket.transform.position;var r=basket.transform.rotation;basket.transform.SetPositionAndRotation(g.checkout.position,g.checkout.rotation);Physics.SyncTransforms();await Frames(2);var checkoutImage=ChristmasIslandQA.Render("Gameplay-Sweet-checkout-postfix",g.checkout.position+Vector3.up*1.1f+Vector3.forward*2.2f,g.checkout.position+Vector3.up*.35f,55);var renderers=basket.GetComponentsInChildren<Renderer>(true).Where(x=>x&&x.enabled).ToArray();var bounds=renderers.Length>0?renderers[0].bounds:GrabBounds(basket);for(int i=1;i<renderers.Length;i++)bounds.Encapsulate(renderers[i].bounds);var data=new{time=DateTime.Now.ToString("s"),mesh=mesh.name,meshTransform=top.position.ToString("F4"),worktopConfigured=g.worktopY,checkout=g.checkout.position.ToString("F4"),basketPivotAtCheckout=basket.transform.position.ToString("F4"),basketRendererBounds=bounds.ToString(),basketBottom=bounds.min.y,checkoutImage,topHorizontalSurfaces=bins.OrderByDescending(x=>x.Value).Take(12).Select(x=>new{worldY=x.Key/100f,projectedArea=x.Value}).ToArray()};var path=Path.GetFullPath("../Game_Plans/SweetCounter_Surface_2026-10-20.json");File.WriteAllText(path,Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));basket.transform.SetPositionAndRotation(p,r);Physics.SyncTransforms();Debug.Log("Sweet counter geometry measurement: "+path+" "+Newtonsoft.Json.JsonConvert.SerializeObject(data));}
