 async Task ProbeCabinetSide(string side){var origin=new Vector3(-29.5f,1.5f,4.2f);foreach(var item in g.sweets){var target=GrabBounds(item).center;hand.transform.SetPositionAndRotation(origin,Quaternion.LookRotation(target-origin,Vector3.up));await Frames(2);var valid=new List<IXRInteractable>();hand.GetValidTargets(valid);var ray=(target-origin);var hits=Physics.RaycastAll(origin,ray.normalized,ray.magnitude+.05f,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).ToArray();string first=hits.Length==0?"none":hits[0].collider.name+"/"+hits[0].collider.GetType().Name;var nodes=new List<string>();for(var t=item.transform;t;t=t.parent)nodes.Add(t.name);nodes.Reverse();results.Add(new{observation="sweet ray reachability",side,item=item.name,itemId=item.itemId,path=string.Join("/",nodes),origin=origin.ToString("F2"),target=target.ToString("F2"),rayFirstHit=first,nearFarTarget=valid.Contains(item.grab)});}}
