 var approach=new Vector3(-29.5f,1.5f,4.2f);async Task<bool> GrabAtStanding(GrabbableItem item,Vector3 destination){await ReleaseAndWait();var center=GrabBounds(item).center;hand.transform.SetPositionAndRotation(approach,Quaternion.LookRotation(center-approach,Vector3.up));await Frames(5);var valid=new List<IXRInteractable>();hand.GetValidTargets(valid);bool hit=valid.Contains(item.grab);Check("Standing 8m cast targets basket "+item.name,hit,$"approach={approach},center={center}");if(!hit)return false;hand.selectInput.QueueManualState(true,1f);await Frames(5);Check("Queued grip selects basket "+item.name,item.IsHeld);if(!item.IsHeld)return false;handToItem=item.transform.position-hand.transform.position;await Move(destination);Release();await Frames(8);return true;}
