 var sweet=g.sweets.First(s=>s.itemId!="Gujiya");await Hold(sweet,sweet.transform.position);await Move(g.basket.transform.position);Release();await Frames(6);Check("Sweet basket can be packed before basket switch guard",g.selected.Count==1);
