 [MenuItem("Diwali/Gameplay/Run Play Mode Verification")]
 public static async void Run(){
 if(!EditorApplication.isPlaying){Debug.LogError("Enter Play Mode before gameplay verification.");return;}
 reportPath="../Game_Plans/Gameplay_RealInput_Full_2026-10-21.json";results.Clear();Save("running");
 try {
  var manager=UnityEngine.Object.FindFirstObjectByType<XRInteractionManager>();
  var h=new GameObject("QA synthetic NearFar controller");var rb=h.AddComponent<Rigidbody>();rb.isKinematic=true;var sphere=h.AddComponent<SphereCollider>();sphere.isTrigger=true;sphere.radius=.05f;hand=h.AddComponent<NearFarInteractor>();hand.interactionManager=manager;hand.enableNearCasting=true;hand.enableUIInteraction=true;hand.selectInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;hand.uiPressInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;var attach=hand.interactionAttachController as UnityEngine.XR.Interaction.Toolkit.Attachment.InteractionAttachController;attach.transformToFollow=h.transform;attach.useMomentum=false;attach.useDistanceBasedVelocityScaling=false;attach.useManipulationInput=false;var far=hand.farInteractionCaster as CurveInteractionCaster;if(far){far.hitDetectionType=CurveInteractionCaster.HitDetectionType.Raycast;far.castDistance=8f;}await Frames();
  var games=UnityEngine.Object.FindObjectsByType<VenueGame>(FindObjectsSortMode.None);
  Check("Exactly five venue games",games.Length==5,"count="+games.Length);
  foreach(var item in UnityEngine.Object.FindObjectsByType<GrabbableItem>(FindObjectsSortMode.None)){
   Check("Visible mesh attached: "+item.itemId,item.GetComponentsInChildren<MeshRenderer>(true).Length>0);
   var activeGrabColliders=item.grab?item.grab.colliders.Where(c=>c&&c.enabled&&c.gameObject.activeInHierarchy).ToArray():Array.Empty<Collider>();Check("Enabled nonempty grab collider set: "+item.itemId,activeGrabColliders.Length>0&&activeGrabColliders.All(c=>GrabBounds(item).size.sqrMagnitude>.00001f));
  }
  Check("XR UI input module active",UnityEngine.Object.FindFirstObjectByType<XRUIInputModule>()!=null);
  Canvas.ForceUpdateCanvases();
  foreach(var g in games){Check(g.GetType().Name+" runtime panel",g.GetComponentInChildren<VenuePanel>()!=null);Check(g.GetType().Name+" restart button",ButtonFor(g,"Restart")!=null);
